      {
        "task": "Creează liste",
        "steps": [
          "Adaugă un h2: <h2>Hobby-urile mele</h2>",
          "Creează o lista neordonata: <ul>",
          "Adaugă 3 elemente: <li>Gaming</li> <li>Muzica</li> <li>Sport</li>",
          "Închide lista: </ul>",
          "Adaugă un h2: <h2>Top 3 materii preferate</h2>",
